      faqs: [{ q: "電動 vs 油圧リフト？", a: "電動（Flying Pig, Paw Bros, SHELANDY）は速いがうるさい。油圧フットポンプ（Master Equipment）は静かで信頼性高 — 不安犬のグルーマー好み。手動（Go Pet Club）は時々の家庭使用のみ。" }, { q: "家庭にリフトテーブル必要？", a: "月次グルーミングならイエス — 腰を守る。四半期のバスのみなら$80 Go Pet Club折畳テーブルで十分。老犬には電動リフトで載せやすい。" }],
      products: { "flying-pig-z-lift-grooming-table": { badge: "🏆", review: "プロ仕様電動。25-48インチ高さ、110kg容量、滑り止めゴム表面。商用サロン使用。", pros: ["電動5.2 cm/秒リフト", "110kg容量", "プロ仕様ビルド"], cons: ["$650-900価格", "うるさいモーター"] }, "master-equipment-grooming-table": { badge: "💪", review: "フットポンプ油圧、110kg容量、91x61cm表面。ヘビーデューティスチールフレーム。静音動作。", pros: ["静音油圧", "ヘビーデューティスチール", "110kg容量"], cons: ["$400-550価格", "遅い2 cm/秒リフト"] }, "paw-bros-electric-grooming-table": { badge: "⚡", review: "電動リフト22-43インチ、100kg容量、デュアルヘビーデューティモーター。折畳アーム＆ノース付属。", pros: ["デュアルモーター", "折畳アーム＋ノース", "100kg容量"], cons: ["$500-700価格", "2mmぐらつき"] }, "go-pet-club-46-grooming-table": { badge: "💸", review: "折畳テーブル、117x61cm、68kg容量。調節アーム＋クランプ付属。家庭用最安。", pros: ["$80-120バジェット", "折畳", "小型犬に68kg"], cons: ["リフトなし", "大型犬不可"] }, "shelandy-electric-grooming-table": { badge: "📐", review: "電動リフト、100kg容量、43インチ天板。収納用折畳。Y型グルーミングアーム。中価格帯電動。", pros: ["中価格帯電動$300-400", "折畳", "Y型アーム"], cons: ["3mmぐらつき", "プレミアム感少ない"] } },
